Translate the following GNU C++17 code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

struct Fraction {
    long long num, den;

    Fraction(long long n = 0, long long d = 1) : num(n), den(d) {}

    long long err(long long x, long long y) const {
        return llabs(den * x - num * y);
    }
};

int main() {
    long long x, y, n;
    scanf("%lld%lld%lld", &x, &y, &n);

    if (y <= n) {
        long long g = __gcd(x, y);
        printf("%lld/%lld", x / g, y / g);
        return 0;
    }

    Fraction best(-1, 0);
    long long i = 1;

    while (i <= n) {
        long long j = i * x / y;
        long long e1 = llabs(i * x - j * y);
        long long e2 = llabs(i * x - (j + 1) * y);
        if (e1 > e2) ++j;

        Fraction cand(j, i);

        if (best.num == -1 ||
            best.err(x, y) * cand.den > cand.err(x, y) * best.den) {
            best = cand;
        }

        ++i;
    }

    printf("%lld/%lld", best.num, best.den);
    return 0;
}
</original_code>
